mapper.update:
update sessions
set created_by_user_id = #{actorUserId}
where session_id = #{sessionId}
  and status = 'ACTIVE'
  and created_by_user_id is null
  and (
      select count(distinct attribution.user_id)
      from (
          select r.triggered_by_user_id as user_id
          from runs r
          where r.session_id = #{sessionId}
            and r.triggered_by_user_id is not null
          union all
          select sm.sender_user_id as user_id
          from session_messages sm
          where sm.session_id = #{sessionId}
            and sm.sender_user_id is not null
            and coalesce(sm.sent_by_shared_user, false) = false
      ) attribution
  ) = 1
  and not exists (
      select 1
      from (
          select r.triggered_by_user_id as user_id
          from runs r
          where r.session_id = #{sessionId}
            and r.triggered_by_user_id is not null
          union all
          select sm.sender_user_id as user_id
          from session_messages sm
          where sm.session_id = #{sessionId}
            and sm.sender_user_id is not null
            and coalesce(sm.sent_by_shared_user, false) = false
      ) attribution
      where attribution.user_id <> #{actorUserId}
  )
